const h2s = (v) => new THREE.Vector3(v[1], v[0], -v[2]);            // Hill → scene (proper rotation)
function quatToScene(q){
  const bx = h2s(Q.rot(q, [1,0,0])), by = h2s(Q.rot(q, [0,1,0])), bz = h2s(Q.rot(q, [0,0,1]));
  const m = new THREE.Matrix4().makeBasis(bx, by, bz);
  return new THREE.Quaternion().setFromRotationMatrix(m);
}
