function makeCanvasTex(size, painter, repeat = 1){
  const cv = document.createElement('canvas'); cv.width = cv.height = size;
  painter(cv.getContext('2d'), size);
  const tx = new THREE.CanvasTexture(cv);
  tx.colorSpace = THREE.SRGBColorSpace;
  tx.wrapS = tx.wrapT = THREE.RepeatWrapping; tx.repeat.set(repeat, repeat);
  tx.anisotropy = 4;
  return tx;
}
function texMLI(){
  return makeCanvasTex(256, (g,s)=>{
    g.fillStyle = '#a87f2c'; g.fillRect(0,0,s,s);
    for (let i=0;i<420;i++){
      const x=visRand.uniform()*s, y=visRand.uniform()*s, w=6+visRand.uniform()*26, h=6+visRand.uniform()*26;
      const b = 105 + visRand.uniform()*115;
      g.fillStyle = `rgb(${b|0},${(b*0.72)|0},${(b*0.22)|0})`;
      g.beginPath(); g.moveTo(x,y); g.lineTo(x+w,y+visRand.uniform()*8-4); g.lineTo(x+w-visRand.uniform()*9,y+h); g.closePath(); g.fill();
    }
  }, 2);
}
