const THR_TORQUE = THR_DEFS.map(t => V.cross(t.pos, t.dir));  // per unit thrust
const GROUPS = {
  'F+X':[0,1],  'F-X':[2,3],  'F+Y':[4,5],  'F-Y':[6,7],  'F+Z':[8,9],  'F-Z':[10,11],
  'T+X':[12,13],'T-X':[14,15],           // roll couples
  'T+Y':[9,10], 'T-Y':[8,11],            // pitch via Z-jets at x offsets
  'T+Z':[4,7],  'T-Z':[5,6],             // yaw via Y-jets at x offsets
};
const ARM = { X:0.80, Y:1.00, Z:1.00 };   // torque moment arms per axis
const MIN_DUTY = 0.04, DUTY_QUANT = 0.05; // min impulse bit / pulse quantisation

/* ---------------- the digital twin ---------------- */
class Sim {
  constructor(seed = 1, scenario = 'nominal'){ this.reset(seed, scenario); }

  reset(seed = this.seed, scenario = this.scenario){
    this.seed = (seed|0) || 1;
    this.scenario = scenario;
    this.rand = new Rand(this.seed);
    const R = this.rand;

    this.t = 0; this.stepIdx = 0; this._acc = 0;

    // ----- truth state (Hill/LVLH, target-centred) -----
    this.r = [-18, -380, 14];                       // m
    this.v = [0.015, 0.32, -0.01];                  // m/s, gentle closing drift
    this.q = lookQuat(V.norm(V.scl(this.r,-1)), [0,0,1]);  // face target
    this.w = [0,0,0];                               // rad/s body

    // target attitude: seeded initial orientation, slow tumble
    const ax = V.norm([R.gauss(), R.gauss(), R.gauss()]);
    this.tq = Q.fromAxisAngle(ax, R.uniform()*Math.PI);
    this.faults = { tumble:true, lidar:false, optical:false, thruster:-1 };
    this.tw = this._tumbleRate();
    this.tInertia = [820, 640, 910];

    // ----- propulsion -----
    this.prop = PROP0;
    this.thr = THR_DEFS.map(() => ({ duty:0, cmdImp:0, achImp:0, cmdTot:0, achTot:0, isolated:false, suspicion:0 }));
    this.Fb_cmd = [0,0,0]; this.Fb_ach = [0,0,0];   // body-frame force this tick, N
    this.Tb_cmd = [0,0,0]; this.Tb_ach = [0,0,0];

    // ----- navigation (EKF on relative translation) -----
    this.est = {
      r: V.add(this.r, [R.gauss()*2.0, R.gauss()*2.0, R.gauss()*2.0]),
      v: V.add(this.v, [R.gauss()*0.02, R.gauss()*0.02, R.gauss()*0.02]),
      P: null, sigPos: 3.5, sigVel: 0.03, tgtAttSig: 0.5,
    };
    const P = Array.from({length:6},()=>new Array(6).fill(0));
    for (let i=0;i<3;i++){ P[i][i]=4.0*4.0/1.5; P[i+3][i+3]=0.03*0.03; }
    this.est.P = P;

    // ----- sensors -----
    this.sens = { lidar:true, optical:true, imu:true, lidarRange:NaN, litFrac:1 };

    // ----- guidance / mission -----
    this.auto = true;
    this.phase = 'ACQUIRE'; this.phaseT = 0;
    this.holdT = 0; this.navHold = false; this.navHoldPos = null;
    this.retreatDir = null; this.safePos = null;
    this.manualCmd = { F:[0,0,0], T:[0,0,0] };
    this.qDes = this.q.slice(); this.attErrDeg = 0;
    this.corridorS = NaN;

    // ----- contact / capture -----
    this.captured = false; this.captureT = 0; this.docked = false;
    this.qRelLock = null; this.contactFails = 0; this.contactCooldown = 0;
    this.lastContact = null;
    this.contact = null;              // live port-to-port metrics

    // ----- bookkeeping -----
    this.events = []; this.history = [];
    this.aborted = false; this.abortReason = null; this._propOutLogged = false;
    this._logGate = {};               // rate-limit repeated log lines
    this._scn = { blackoutFired:false, blackoutEnd:0, thrFired:false };

    // scenario presets
    if (scenario === 'stuck-thruster'){ /* jet C1 dies at t=40 s, see _scenarioScript */ }
    this.log('info', `Scenario "${scenario}" initialised · seed ${this.seed} · target range ${fmt(V.len(this.r),0)} m`);
    this.log('phase', 'ACQUIRE — converging relative navigation before first burn.');
  }

  _tumbleRate(){
    return this.faults.tumble
      ? [0.25*RAD, 0.45*RAD, 0.18*RAD].map((x,i)=>x*(i===1?1:1))   // ~0.55°/s total
      : [0.02*RAD, 0.012*RAD, 0.016*RAD];
  }

  /* ---------- event log ---------- */
  log(level, msg, gateKey = null, gateSec = 0){
    if (gateKey){
      const last = this._logGate[gateKey];
      if (last !== undefined && this.t - last < gateSec) return;
      this._logGate[gateKey] = this.t;
    }
    this.events.push({ t: this.t, level, msg });
    if (this.events.length > 400) this.events.splice(0, this.events.length - 400);
  }
  setPhase(p, why){
    if (this.phase === p) return;
    this.phase = p; this.phaseT = 0;
    this.log(p==='HARD DOCK'||p==='SOFT CAPTURE' ? 'success' : (p==='ABORT'?'abort':'phase'), `${p} — ${why}`);
  }

  /* ---------- faults ---------- */
  setFault(name, on, jet = -1){
    const f = this.faults;
    if (name === 'tumble'){
      f.tumble = on; this.tw = this._tumbleRate();
      this.log('info', on ? 'Fault injected: target tumble spun up to ~0.55°/s.' : 'Target tumble cleared — residual rates only.');
    } else if (name === 'lidar'){
      f.lidar = on; this.log(on?'caution':'info', on ? 'Fault injected: lidar returns lost.' : 'Lidar returns restored.');
    } else if (name === 'optical'){
      f.optical = on; this.log(on?'caution':'info', on ? 'Fault injected: optical tracker blind.' : 'Optical tracker restored.');
    } else if (name === 'thruster'){
      if (on){
        f.thruster = jet;
        this.log('caution', `Fault injected: jet ${THR_DEFS[jet].id} valve stuck closed (undetected).`);
      } else {
        const old = f.thruster; f.thruster = -1;
        if (old >= 0 && this.thr[old].isolated){
          this.thr[old].isolated = false; this.thr[old].suspicion = 0;
          this.log('info', `Maintenance: jet ${THR_DEFS[old].id} fault cleared — FDIR isolation lifted, jet back in the pool.`);
        } else if (old >= 0){
          this.log('info', `Fault on jet ${THR_DEFS[old].id} cleared.`);
        }
      }
    }
  }
  abort(reason){
    if (this.docked || this.phase === 'ABORT' || this.phase === 'SAFE HOLD') return;
    this.aborted = true; this.abortReason = reason; this.auto = true;
    this.captured = false; this.qRelLock = null;
    const rr = V.len(this.est.r) > 1 ? V.norm(this.est.r) : [0,-1,0];
    this.retreatDir = rr;
    this.setPhase('ABORT', `${reason}. Opening range along the safe retreat vector; burns toward the target are inhibited.`);
  }
  replan(){
    if (this.docked) return;
    this.aborted = false; this.abortReason = null; this.navHold = false; this.holdT = 0; this.auto = true;
    const r = V.len(this.est.r), c = this.contact;
    const inCone = !!c && c.axial > 0.5 && c.lateral < Math.tan(CORR_HALF)*Math.max(c.axial,2) + 0.3;
    let p = 'FAR APPROACH';
    if (r < 55 && inCone) p = 'FINAL CORRIDOR';
    else if (r < 170) p = 'PROX APPROACH';
    if (p === this.phase) this.log('info', `Re-plan accepted at ${fmt(r,0)} m — continuing ${p}.`);
    this.setPhase(p, `re-plan accepted at ${fmt(r,0)} m range — resuming the autonomous sequence.`);
  }

  /* ---------- public stepping ---------- */
  advance(seconds){                       // fixed-step, remainder carried
    this._acc += seconds;
    let n = Math.floor(this._acc / DT + 1e-9);
    this._acc -= n * DT;
    while (n-- > 0) this.stepOnce();
  }

  stepOnce(){
    if (this.stepIdx % STEPS_PER_CTRL === 0) this._ctrlTick();
    this._physicsStep();
    this.t += DT; this.stepIdx++; this.phaseT += DT;
    if (this.contactCooldown > 0) this.contactCooldown -= DT;
    this._contactCheck();
    if (this.docked) this._dockedKinematics();
  }

  /* =============== control tick: sensors → nav → FDIR → guidance → allocation =============== */
  _ctrlTick(){
    const R = this.rand;
    // -- draw the tick's full noise vector unconditionally (keeps runs comparable across fault timelines)
    const nz = {
      lidarR: R.gauss(), lidarRR: R.gauss(),
      opt: [R.gauss(), R.gauss(), R.gauss()],
      imuA: [R.gauss(), R.gauss(), R.gauss()],
      imuW: [R.gauss(), R.gauss(), R.gauss()],
    };

    this._scenarioScript();

    // -- illumination (drives optical availability + scene lighting)
    const psi = 40*RAD - N_ORB * this.t;
    const cb = Math.cos(22*RAD), sb = Math.sin(22*RAD);
    this.sunDir = [cb*Math.cos(psi), cb*Math.sin(psi), sb];      // Hill frame, toward sun
    const cosE = -this.sunDir[0];                                 // dot(sun, earthDir=-x)
    this.sens.litFrac = 1 - clamp((cosE - 0.30) / 0.08, 0, 1);    // 1 lit → 0 umbra

    const rangeTrue = V.len(this.r);
    const wasL = this.sens.lidar, wasO = this.sens.optical;
    this.sens.lidar   = !this.faults.lidar && rangeTrue < 600 && this.prop >= 0;
    this.sens.optical = !this.faults.optical && this.sens.litFrac > 0.12;
    if (wasO && !this.sens.optical && this.sens.litFrac <= 0.12)
      this.log('caution', 'Optical tracker lost lock: target in eclipse shadow.', 'optEcl', 30);
    if (!wasL && this.sens.lidar && this.t > 1) this.log('info', 'Lidar track re-acquired.', 'lidBack', 5);
    if (!wasO && this.sens.optical && this.t > 1) this.log('info', 'Optical track re-acquired.', 'optBack', 5);

    // -- previous-tick achieved thrust, as sensed by the IMU (specific force)
    const m = MASS_DRY + Math.max(this.prop, 0);
    const dvExp = V.scl(this.Fb_cmdKnown || [0,0,0], CTRL_DT / m);   // what allocator believed it commanded
    const dvAch = V.scl(this.Fb_ach, CTRL_DT / m);
    const dvMeas = V.add(dvAch, V.scl(nz.imuA, 0.0003));
    const dwExp = this.Tb_cmdKnown ? this.Tb_cmdKnown.map((x,i)=>x*CTRL_DT/INERTIA[i]) : [0,0,0];
    const dwMeas = this.Tb_ach.map((x,i)=>x*CTRL_DT/INERTIA[i] + nz.imuW[i]*2e-5);

    this._fdir(dvExp, dvMeas, dwExp, dwMeas);

    // -- EKF predict (uses IMU-measured specific force rotated to Hill — survives unknown jet failures)
    const aMeasHill = Q.rot(this.q, V.scl(dvMeas, 1/CTRL_DT));
    this._ekfPredict(aMeasHill);

    // -- EKF updates
    if (this.sens.lidar){
      const zR  = rangeTrue + nz.lidarR * (0.02 + 0.0012*rangeTrue);
      const rr  = V.dot(this.r, this.v) / Math.max(rangeTrue, 1e-6);
      const zRR = rr + nz.lidarRR * 0.008;
      this._ekfRange(zR, Math.pow(0.02 + 0.0012*rangeTrue, 2));
      this._ekfRangeRate(zRR, 0.008*0.008);
      this.sens.lidarRange = zR;
    } else this.sens.lidarRange = NaN;
    if (this.sens.optical){
      const sigA = 0.0028;                                        // ~0.16° bearing noise
      let u = V.norm(this.r);
      // perturb perpendicular to the line of sight
      let p1 = V.norm(V.cross(u, Math.abs(u[0])<0.9?[1,0,0]:[0,1,0]));
      let p2 = V.cross(u, p1);
      u = V.norm(V.add(u, V.add(V.scl(p1, nz.opt[0]*sigA), V.scl(p2, nz.opt[1]*sigA))));
      this._ekfBearing(u, sigA*sigA);
    }
    this._ekfFinalize();

    // -- target-attitude knowledge (optical marker tracking inside 150 m)
    const optAtt = this.sens.optical && rangeTrue < 150;
    const twMag = V.len(this.tw)*DEG;
    if (optAtt) this.est.tgtAttSig = Math.max(0.3, this.est.tgtAttSig - 0.25*CTRL_DT*this.est.tgtAttSig);
    else        this.est.tgtAttSig = Math.min(45, this.est.tgtAttSig + (0.02 + 0.35*twMag)*CTRL_DT);

    // -- port geometry (truth attitude; knowledge quality is gated by tgtAttSig)
    this._updateContactMetrics();

    // -- guidance & safety
    let Fh = [0,0,0], Tb = [0,0,0], wDesB = [0,0,0];
    if (this.docked || this.prop <= 0){
      this.qDes = this.q.slice();
    } else if (this.captured){
      ({Fh, Tb} = this._captureControl());
    } else if (!this.auto){
      ({Fh, Tb} = this._manualControl());
      this._safetyMonitor();
    } else {
      ({Fh, Tb, wDesB} = this._autoGuidance());
      this._safetyMonitor();
    }

    // attitude error telemetry vs current desired
    this.attErrDeg = Q.angleBetween(this.q, this.qDes) * DEG;

    // -- allocate to jets
    this._allocate(Fh, Tb);

    // -- history for plots
    const closing = -V.dot(this.est.r, this.est.v) / Math.max(V.len(this.est.r), 1e-6);
    this.history.push({ t:this.t, range:V.len(this.est.r), close:closing, prop:this.prop,
                        att:this.attErrDeg, sig:this.est.sigPos });
    if (this.history.length > 1500) this.history.splice(0, this.history.length - 1500);
  }

  /* ---------- scripted scenario beats (deterministic, state-triggered) ---------- */
  _scenarioScript(){
    const s = this._scn;
    if (this.scenario === 'sensor-blackout' && !s.blackoutFired
        && this.phase === 'FINAL CORRIDOR' && this.contact && this.contact.axial < 26){
      s.blackoutFired = true; s.blackoutEnd = this.t + 75;
      this.setFault('lidar', true); this.setFault('optical', true);
      this.log('warn', 'SCENARIO EVENT: full navigation sensor blackout during proximity operations.');
    }
    if (this.scenario === 'sensor-blackout' && s.blackoutFired && s.blackoutEnd > 0 && this.t >= s.blackoutEnd){
      s.blackoutEnd = 0;
      this.setFault('lidar', false); this.setFault('optical', false);
      this.log('info', 'SCENARIO EVENT: sensor blackout ends — filters should reconverge.');
    }
    if (this.scenario === 'stuck-thruster' && !s.thrFired && this.t >= 40){
      s.thrFired = true;
      this.setFault('thruster', true, 0);       // A1: +X jet — allocator must rebalance the axial burns
    }
  }

  /* ---------- FDIR: compare expected vs sensed response, isolate dead jets ---------- */
  _fdir(dvExp, dvMeas, dwExp, dwMeas){
    const resF = V.sub(dvExp, dvMeas);
    const resT = V.sub(dwExp, dwMeas);
    const expMag = V.len(dvExp), resMag = V.len(resF);
    const expT = V.len(dwExp), resTMag = V.len(resT);
    const sigF = resMag > 0.30*expMag + 0.0012 && expMag > 0.002;
    const sigT = resTMag > 0.35*expT + 6e-5 && expT > 5e-5;
    for (let i=0;i<16;i++){
      const th = this.thr[i];
      if (th.isolated){ continue; }
      let ev = 0;
      if (th.duty > 0.03){
        if (sigF && resMag > 1e-9){
          const c = V.dot(V.norm(resF), THR_DEFS[i].dir);
          if (c > 0.45) ev += th.duty * c;
        }
        if (sigT && resTMag > 1e-12){
          const tq = V.norm(THR_TORQUE[i]);
          const c = V.dot(V.norm(resT), tq);
          if (c > 0.45) ev += 0.8 * th.duty * c;
        }
      }
      th.suspicion = Math.max(0, th.suspicion * 0.992 + ev);
      if (th.suspicion > 2.6){
        th.isolated = true;
        this.log('warn', `FDIR: jet ${THR_DEFS[i].id} declared FAILED — commanded pulses produce no sensed Δv/Δω (residual ${(resMag*1000).toFixed(1)} mm/s). Jet isolated; allocator reconfigured with torque compensation. Expect higher propellant use.`);
      }
    }
  }

  /* ---------- EKF ---------- */
  _ekfPredict(aHill){
    const dt = CTRL_DT, n = N_ORB, e = this.est;
    // state
    const a = V.add(cwAccel(e.r, e.v), aHill);
    e.v = V.add(e.v, V.scl(a, dt));
    e.r = V.add(e.r, V.scl(e.v, dt));
    // F = I + A dt
    const F = Array.from({length:6},(_,i)=>Array.from({length:6},(_,j)=>i===j?1:0));
    F[0][3]=dt; F[1][4]=dt; F[2][5]=dt;
    F[3][0]= 3*n*n*dt; F[3][4]= 2*n*dt;
    F[4][3]=-2*n*dt;
    F[5][2]=-n*n*dt;
    const P = e.P, FP = Array.from({length:6},()=>new Array(6).fill(0));
    for (let i=0;i<6;i++) for (let k=0;k<6;k++){ const f=F[i][k]; if (f) for (let j=0;j<6;j++) FP[i][j]+=f*P[k][j]; }
    const NP = Array.from({length:6},()=>new Array(6).fill(0));
    for (let i=0;i<6;i++) for (let j=0;j<6;j++){ let s=0; for (let k=0;k<6;k++){ const f=F[j][k]; if (f) s+=FP[i][k]*f; } NP[i][j]=s; }
    // process noise (unmodelled accel / IMU error ~1.5e-3 m/s^2 RMS)
    const qa = 1.5e-3, q2 = qa*qa;
    for (let i=0;i<3;i++){
      NP[i][i]     += 0.25*q2*Math.pow(dt,4);
      NP[i+3][i+3] += q2*dt*dt;
      NP[i][i+3]   += 0.5*q2*Math.pow(dt,3);
      NP[i+3][i]   += 0.5*q2*Math.pow(dt,3);
    }
    e.P = NP;
  }
  _ekfScalar(z, h, H, Rm){                 // one scalar measurement, H is 6-vector
    const e = this.est, P = e.P;
    const PH = new Array(6).fill(0);
    for (let i=0;i<6;i++){ let s=0; for (let j=0;j<6;j++) s += P[i][j]*H[j]; PH[i]=s; }
    let S = Rm; for (let i=0;i<6;i++) S += H[i]*PH[i];
    if (S <= 1e-12) return;
    const y = z - h, K = PH.map(x=>x/S);
    e.r = [e.r[0]+K[0]*y, e.r[1]+K[1]*y, e.r[2]+K[2]*y];
    e.v = [e.v[0]+K[3]*y, e.v[1]+K[4]*y, e.v[2]+K[5]*y];
    for (let i=0;i<6;i++) for (let j=0;j<6;j++) P[i][j] -= K[i]*PH[j];
  }
  _ekfRange(z, Rm){
    const e = this.est, rr = V.len(e.r); if (rr < 1e-6) return;
    const u = V.scl(e.r, 1/rr);
    this._ekfScalar(z, rr, [u[0],u[1],u[2],0,0,0], Rm);
  }
  _ekfRangeRate(z, Rm){
    const e = this.est, rr = V.len(e.r); if (rr < 1e-6) return;
    const rv = V.dot(e.r, e.v), h = rv/rr, u = V.scl(e.r, 1/rr);
    const Hr = [
      (e.v[0]*rr - rv*u[0]) / (rr*rr),
      (e.v[1]*rr - rv*u[1]) / (rr*rr),
      (e.v[2]*rr - rv*u[2]) / (rr*rr)];
    this._ekfScalar(z, h, [Hr[0],Hr[1],Hr[2],u[0],u[1],u[2]], Rm);
  }
  _ekfBearing(uMeas, Rm){
    const e = this.est, rr = V.len(e.r); if (rr < 1e-6) return;
    const u = V.scl(e.r, 1/rr);
    for (let k=0;k<3;k++){
      // h_k = r_k/|r| ; dh/dr row = (I - u uT)/|r|
      const H = new Array(6).fill(0);
      for (let j=0;j<3;j++) H[j] = ((k===j?1:0) - u[k]*u[j]) / rr;
      this._ekfScalar(uMeas[k], u[k], H, Rm);
    }
  }
  _ekfFinalize(){
    const P = this.est.P;
    for (let i=0;i<6;i++) for (let j=i+1;j<6;j++){ const m=(P[i][j]+P[j][i])/2; P[i][j]=m; P[j][i]=m; }
    for (let i=0;i<6;i++) P[i][i] = Math.max(P[i][i], 1e-10);
    this.est.sigPos = Math.sqrt(P[0][0]+P[1][1]+P[2][2]);
    this.est.sigVel = Math.sqrt(P[3][3]+P[4][4]+P[5][5]);
  }

  /* ---------- port-to-port geometry & rates ---------- */
  _updateContactMetrics(){
    const axis = Q.rot(this.tq, [1,0,0]);                    // target port outward normal (Hill)
    const pT = Q.rot(this.tq, PORT_T);
    const pC = V.add(this.r, Q.rot(this.q, PORT_C));
    const d = V.sub(pC, pT);
    const axial = V.dot(d, axis);
    const latV = V.sub(d, V.scl(axis, axial));
    const wT = Q.rot(this.tq, this.tw);                      // target ang vel, Hill
    const wC = Q.rot(this.q, this.w);
    const vT = V.cross(wT, pT);
    const vC = V.add(this.v, V.cross(wC, Q.rot(this.q, PORT_C)));
    const vRel = V.sub(vC, vT);
    const dirC = Q.rot(this.q, [1,0,0]);
    this.contact = {

    axis, pT, pC,
    dist: V.len(d), axial, lateral: V.len(latV),
    closing: -V.dot(vRel, axis),                           // + when ports approach
    vRel,
    align: Math.acos(clamp(-V.dot(dirC, axis), -1, 1)) * DEG,
    relRate: V.len(V.sub(wC, wT)) * DEG,
  };
  this.corridorS = axial;
}
gatesPass(c = this.contact){
  return {
    range:  c.dist   <  GATE.range + 0.02,
    speed:  c.closing >= GATE.vmin && c.closing <= GATE.vmax,
    lat:    c.lateral <  GATE.lat,
    align:  c.align   <  GATE.align,
    rate:   c.relRate <  GATE.rate,
  };
}

/* ---------- guidance helpers ---------- */
_vmaxAt(range){ return 0.10 + 0.012*range; }               // closing-rate safety envelope, m/s
_trackPoint(wp, wpVel, speedCap){
  // velocity command: feed-forward + position PD, then force via velocity loop
  const e = this.est;
  const toWp = V.sub(wp, e.r);
  let vCmd = V.add(wpVel, V.clampLen(V.scl(toWp, 0.09), speedCap));
  const m = MASS_DRY + Math.max(this.prop,0);
  const aff = cwAccel(e.r, e.v);
  let F = V.scl(V.add(V.scl(V.sub(vCmd, e.v), 0.38), V.scl(aff, -1)), m);
  return V.clampLen(F, 2*THRUST);
}
_attCmd(qDes, wDesB){
  this.qDes = qDes;
  let qe = Q.mul(Q.conj(qDes), this.q);
  if (qe[0] < 0) qe = qe.map(x=>-x);
  const errV = [2*qe[1], 2*qe[2], 2*qe[3]];                // rad, ~body frame
  const kp = 0.028, kd = 0.30;
  const T = [0,1,2].map(i => INERTIA[i] * (-kp*errV[i] - kd*(this.w[i]-wDesB[i])));
  const cap = [2*THRUST*ARM.X, 2*THRUST*ARM.Y, 2*THRUST*ARM.Z];
  return T.map((x,i)=>clamp(x, -cap[i], cap[i]));
}

/* ---------- autonomous guidance state machine ---------- */
_autoGuidance(){
  const e = this.est, c = this.contact;
  const range = V.len(e.r);
  const rHat = range > 0.5 ? V.norm(e.r) : [0,-1,0];
  let Fh = [0,0,0], Tb = [0,0,0], wDesB = [0,0,0];
  let qDes = lookQuat(V.scl(rHat,-1), [0,0,1]);            // default: face the target

  const sensorsOk = this.sens.lidar || this.sens.optical;
  const wT_hill = Q.rot(this.tq, this.tw);

  switch (this.phase){
    case 'ACQUIRE': {
      if (this.phaseT > 8 && e.sigPos < 2.5)
        this.setPhase('FAR APPROACH', `navigation converged (σ=${fmt(e.sigPos,2)} m < 2.5 m gate). Burning for the 150 m V-bar hold point.`);
      break;
    }
    case 'FAR APPROACH': {
      const wp = [0,-150,0];
      Fh = this._trackPoint(wp, [0,0,0], Math.min(1.2, 0.10+0.015*V.len(V.sub(wp,e.r))));
      if (V.len(V.sub(wp, e.r)) < 8 && V.len(e.v) < 0.20)
        this.setPhase('HOLD POINT', 'arrived at 150 m V-bar station. Holding to verify nav quality and sensor health before proximity ops.');
      break;
    }
    case 'HOLD POINT': {
      Fh = this._trackPoint([0,-150,0], [0,0,0], 0.4);
      this.holdT += CTRL_DT;
      if (this.holdT > 20 && e.sigPos < 1.2 && sensorsOk)
        this.setPhase('PROX APPROACH', `hold complete (σ=${fmt(e.sigPos,2)} m, sensors healthy). Proceeding to the corridor entry gate at 38 m.`);
      else if (this.holdT > 20 && !sensorsOk)
        this.log('caution', 'Holding at 150 m: waiting on a valid nav sensor before committing to proximity operations.', 'holdWait', 20);
      else if (this.holdT > 20 && e.sigPos >= 1.2)
        this.log('caution', `Holding at 150 m: nav σ ${fmt(e.sigPos,2)} m still above the 1.2 m proximity gate.`, 'holdSig', 20);
      break;
    }
    case 'PROX APPROACH': {
      const entry = V.add(c.pT, V.scl(c.axis, 38));
      const entryVel = V.cross(wT_hill, entry);
      if (this._navDegradedHold(range, 'PROX APPROACH')) { Fh = this._holdF; break; }
      Fh = this._trackPoint(entry, entryVel, Math.min(0.55, this._vmaxAt(range)*0.8));
      if (V.len(V.sub(entry, e.r)) < 2.5 && this.attErrDeg < 15){
        this.setPhase('FINAL CORRIDOR', `at corridor entry, ${fmt(c.dist,1)} m from the port. Matching tumble (${fmt(V.len(this.tw)*DEG,2)}°/s) and descending the cone.`);
      }
      break;
    }
    case 'FINAL CORRIDOR': {
      qDes = lookQuat(V.scl(c.axis,-1), Q.rot(this.tq,[0,0,1]));
      wDesB = Q.rotInv(this.q, wT_hill);
      if (this._navDegradedHold(range, 'FINAL CORRIDOR')) { Fh = this._holdF; break; }
      const s = Math.max(c.axial, 0.05);
      const vDes = Math.min(0.035 + 0.012*s, 0.8*this._vmaxAt(range));
      // CoM point that keeps our port on the (rotating) corridor axis at the current standoff,
      // then command closing speed directly along the axis + rotation feed-forward + lateral pull
      const wpCoM = V.sub(V.add(c.pT, V.scl(c.axis, s)), Q.rot(this.q, PORT_C));
      const vCmd = V.add(V.add(V.cross(wT_hill, wpCoM), V.scl(c.axis, -vDes)),
                         V.clampLen(V.scl(V.sub(wpCoM, e.r), 0.30), 0.15));
      const mC = MASS_DRY + Math.max(this.prop, 0);
      Fh = V.clampLen(V.scl(V.add(V.scl(V.sub(vCmd, e.v), 0.42), V.scl(cwAccel(e.r, e.v), -1)), mC), 2*THRUST);
      break;
    }
    case 'ABORT': {
      qDes = lookQuat(V.scl(rHat,-1), [0,0,1]);
      const vCmd = V.scl(this.retreatDir, 0.6);
      const m = MASS_DRY + Math.max(this.prop,0);
      Fh = V.clampLen(V.scl(V.sub(vCmd, e.v), 0.38*m), 2*THRUST);
      if (range > 90){
        this.safePos = e.r.slice();
        this.setPhase('SAFE HOLD', `range opened to ${fmt(range,0)} m, outside all safety volumes. Station-keeping; awaiting re-plan.`);
      }
      break;
    }
    case 'SAFE HOLD': {
      Fh = this._trackPoint(this.safePos || [0,-120,0], [0,0,0], 0.3);
      break;
    }
    case 'SOFT CAPTURE': case 'HARD DOCK': break;
  }
  Tb = this._attCmd(qDes, wDesB);
  return { Fh, Tb, wDesB };
}
_navDegradedHold(range, phaseName){
  const e = this.est;
  const degradedPos = e.sigPos > 0.6;
  const degradedAtt = e.tgtAttSig > 4 && range < 55;
  if (degradedPos || degradedAtt){
    if (!this.navHold){
      this._blindAxis = this.contact ? this.contact.axis.slice() : V.norm(e.r);
      const why = degradedPos
        ? `nav σ grew to ${fmt(e.sigPos,2)} m (0.6 m blind gate)`
        : `target-attitude knowledge degraded to ±${fmt(e.tgtAttSig,1)}° (4° gate) — the corridor axis can no longer be trusted`;
      if (range < KOS_R + 6)
        this.log('warn', `${phaseName}: ${why} while inside the keep-out region. Backing out along the last-known corridor axis until track recovers.`);
      else
        this.log('caution', `${phaseName}: ${why} — holding position, coasting on the filter until measurements return.`);
    }
    this.navHold = true;
    const m = MASS_DRY + Math.max(this.prop, 0);
    if (range < KOS_R + 6){
      const vCmd = V.scl(this._blindAxis, 0.15);           // blind back-out, away from structure
      this._holdF = V.clampLen(V.scl(V.sub(vCmd, e.v), 0.38*m), 2*THRUST);
    } else {
      this._holdF = V.clampLen(V.scl(e.v, -0.38*m), 2*THRUST);   // null rates and wait
    }
    return true;
  }
  if (this.navHold){
    const c = this.contact;
    const allowed = c ? Math.tan(CORR_HALF)*Math.max(c.axial,2) + 0.3 : Infinity;
    const corridorInvalid = this.phase === 'FINAL CORRIDOR' && c && (c.lateral > allowed || c.axial > 40);
    if (corridorInvalid && range < KOS_R + 4){
      // measurements are back but the corridor rotated away while we were blind:
      // finish backing out with good nav before re-entering
      const m = MASS_DRY + Math.max(this.prop, 0);
      const vCmd = V.scl(V.norm(e.r), 0.15);
      this._holdF = V.clampLen(V.scl(V.sub(vCmd, e.v), 0.38*m), 2*THRUST);
      this.log('info', 'Track recovered; continuing the back-out to a safe standoff before re-entering the corridor.', 'reentry', 20);
      return true;
    }
    this.navHold = false;
    this.log('info', `${phaseName}: navigation recovered (σ=${fmt(e.sigPos,2)} m, tgt-att ±${fmt(e.tgtAttSig,1)}°) — resuming the approach.`);
    if (corridorInvalid){
      this.setPhase('PROX APPROACH', `the corridor rotated ${fmt(c.lateral,1)} m off our position during the blackout — re-entering through the 38 m gate.`);
      return false;
    }
  }
  return false;
}

/* ---------- manual control ---------- */
_manualControl(){
  const mc = this.manualCmd;
  const Fb = V.scl(mc.F, 2*THRUST);
  const Tb = [mc.T[0]*2*THRUST*ARM.X*0.5, mc.T[1]*2*THRUST*ARM.Y*0.5, mc.T[2]*2*THRUST*ARM.Z*0.5];
  this.qDes = this.q.slice();
  return { Fh: Q.rot(this.q, Fb), Tb };
}

/* ---------- soft-capture servo ---------- */
_captureControl(){
  // let RCS relax; the mechanism (spring/damper in physics) does the work. Null body rates gently.
  const Tb = [0,1,2].map(i => INERTIA[i] * (-0.25*this.w[i]));
  this.qDes = this.q.slice();
  return { Fh:[0,0,0], Tb };
}

/* ---------- safety monitor (runs in AUTO and MANUAL) ---------- */
_safetyMonitor(){
  const e = this.est, c = this.contact;
  const range = V.len(e.r);
  const closing = -V.dot(e.r, e.v) / Math.max(range, 1e-6);
  const phaseCorr = this.phase === 'FINAL CORRIDOR' || this.phase === 'SOFT CAPTURE';
  const inCone = !!c && c.axial > -0.5 && c.lateral < Math.tan(CORR_HALF)*Math.max(c.axial,2) + 0.3;
  const inCorr = phaseCorr || (!this.auto && inCone);   // manual flying inside the cone is legal
  this.safety = { range, closing, vmax: this._vmaxAt(range), kosMargin: range - KOS_R,
                  corrAllowed: inCorr ? Math.tan(CORR_HALF)*Math.max(c.axial,2) + 0.3 : NaN,
                  corrOffset: inCorr ? c.lateral : NaN };
  if (this.docked || this.phase === 'ABORT' || this.phase === 'SAFE HOLD') return;

  if (!inCorr && range < KOS_R){
    this.abort(`SAFETY: keep-out sphere breached at ${fmt(range,1)} m outside an approved corridor`);
    return;
  }
  if (inCorr){
    const allowed = this.safety.corrAllowed;
    if (!this.navHold && (c.axial < -0.5 || c.lateral > allowed * 1.35)){
      this.abort(`SAFETY: departed the approach corridor (offset ${fmt(c.lateral,1)} m > ${fmt(allowed*1.35,1)} m limit)`);
      return;
    }
    if (this.navHold && c.lateral > allowed)
      this.log('caution', `Blind drift is carrying the vehicle off the corridor axis (offset ${fmt(c.lateral,1)} m) — corridor enforcement deferred until nav recovers.`, 'blindCorr', 15);
    else if (c.lateral > allowed)
      this.log('caution', `Corridor offset ${fmt(c.lateral,2)} m exceeds the ${fmt(allowed,2)} m cone — guidance is steering back to the axis.`, 'corrOff', 10);
  }
  if (closing > this._vmaxAt(range) * 1.35 && range < 250){
    this.abort(`SAFETY: closing rate ${fmt(closing,2)} m/s exceeds ${fmt(this._vmaxAt(range)*1.35,2)} m/s hard limit at ${fmt(range,0)} m`);
    return;
  }
  if (closing > this._vmaxAt(range) && range < 250)
    this.log('caution', `Closing ${fmt(closing,2)} m/s above the ${fmt(this._vmaxAt(range),2)} m/s envelope — braking.`, 'rate', 8);
  const propFrac = this.prop / PROP0;
  if (propFrac < 0.06){ this.abort('SAFETY: propellant below the 6% abort reserve'); return; }
  if (propFrac < 0.14) this.log('caution', `Propellant at ${(propFrac*100).toFixed(0)}% — approaching the abort reserve.`, 'prop', 30);
  if (this.contactFails >= 3){ this.abort('SAFETY: three failed contact attempts — structure risk'); }
}

/* ---------- thruster allocation (2-pass, reconfigurable) ---------- */
_allocate(Fh, TbIn){
  const Fb = Q.rotInv(this.q, Fh);
  const duty = new Array(16).fill(0);
  const avail = i => !this.thr[i].isolated;
  const addGroup = (name, amount) => {
    for (const i of GROUPS[name]) if (avail(i)) duty[i] += amount;
  };
  // pass A: forces
  const axes = ['X','Y','Z'];
  for (let k=0;k<3;k++){
    const want = Math.abs(Fb[k]) / (2*THRUST);
    if (want > 1e-4) addGroup((Fb[k]>0?'F+':'F-')+axes[k], Math.min(want, 1));
  }
  // predicted torque from pass A with the *known-good* jets (reconfiguration knowledge)
  const tPred = [0,0,0];
  for (let i=0;i<16;i++) if (duty[i]>0 && avail(i)){
    const tq = THR_TORQUE[i];
    tPred[0]+=duty[i]*THRUST*tq[0]; tPred[1]+=duty[i]*THRUST*tq[1]; tPred[2]+=duty[i]*THRUST*tq[2];
  }
  // pass B: torques (desired minus what pass A already produces)
  const Tb = V.sub(TbIn, tPred);
  const arms = [ARM.X, ARM.Y, ARM.Z];
  for (let k=0;k<3;k++){
    const want = Math.abs(Tb[k]) / (2*THRUST*arms[k]);
    if (want > 1e-4) addGroup((Tb[k]>0?'T+':'T-')+axes[k], Math.min(want, 1));
  }
  // quantise to pulse bits, clamp (saturation)
  const m = MASS_DRY + Math.max(this.prop, 0);
  this.Fb_cmd = [0,0,0]; this.Tb_cmd = [0,0,0];
  this.Fb_cmdKnown = [0,0,0]; this.Tb_cmdKnown = [0,0,0];
  this.Fb_ach = [0,0,0]; this.Tb_ach = [0,0,0];
  let propUsed = 0;
  for (let i=0;i<16;i++){
    let d = clamp(duty[i], 0, 1);
    d = Math.round(d / DUTY_QUANT) * DUTY_QUANT;
    if (d < MIN_DUTY) d = 0;
    if (this.thr[i].isolated) d = 0;                        // FDIR removed it from the pool
    this.thr[i].duty = d;
    const imp = d * THRUST * CTRL_DT;                       // commanded impulse this tick
    this.thr[i].cmdImp = imp; this.thr[i].cmdTot += imp;
    const dead = this.faults.thruster === i || this.prop <= 0;
    const ach = dead ? 0 : imp;
    this.thr[i].achImp = ach; this.thr[i].achTot += ach;
    const dir = THR_DEFS[i].dir, tq = THR_TORQUE[i];
    for (let k=0;k<3;k++){
      this.Fb_cmd[k] += imp/CTRL_DT * dir[k];
      this.Tb_cmd[k] += imp/CTRL_DT * tq[k];
      this.Fb_cmdKnown[k] += imp/CTRL_DT * dir[k];          // allocator belief (isolated jets already 0)
      this.Tb_cmdKnown[k] += imp/CTRL_DT * tq[k];
      this.Fb_ach[k] += ach/CTRL_DT * dir[k];
      this.Tb_ach[k] += ach/CTRL_DT * tq[k];
    }
    propUsed += ach / (ISP * G0);
  }
  if (this.prop > 0) this.prop = Math.max(0, this.prop - propUsed);
  else if (this.prop <= 0 && !this._propOutLogged){ this._propOutLogged = true; this.log('warn','Propellant exhausted — RCS inert. Vehicle is ballistic.'); }
}

/* ---------- physics substep (DT) ---------- */
_physicsStep(){
  const m = MASS_DRY + Math.max(this.prop, 0);
  // thrust force follows the body as it rotates within the tick
  let Fh = Q.rot(this.q, this.Fb_ach);
  let Tb = this.Tb_ach.slice();

  // soft-capture mechanism: spring-damper between the two port rings
  if (this.captured && !this.docked && this.contact){
    this._updateContactMetrics();
    const c = this.contact;
    const stretch = V.sub(c.pC, c.pT);
    const Fspring = V.add(V.scl(stretch, -260), V.scl(c.vRel, -190));
    Fh = V.add(Fh, Fspring);
    // alignment torque: pull chaser port axis onto -target axis, damp relative rates
    const wT_hill = Q.rot(this.tq, this.tw);
    const qAim = lookQuat(V.scl(c.axis,-1), Q.rot(this.tq,[0,0,1]));
    let qe = Q.mul(Q.conj(qAim), this.q);
    if (qe[0] < 0) qe = qe.map(x=>-x);
    const wDesB = Q.rotInv(this.q, wT_hill);
    for (let k=0;k<3;k++) Tb[k] += INERTIA[k]*(-0.35*2*qe[k+1] - 1.1*(this.w[k]-wDesB[k]));
    this.captureT += DT;
    if (V.len(stretch) > 0.55){
      this.captured = false; this.captureT = 0; this.contactFails++;
      this.log('warn', 'Soft capture LOST — residual motion overpowered the capture mechanism before latching. Backing off.');
      this.setPhase('FINAL CORRIDOR', 'capture release; re-running the final corridor.');
    } else if (this.captureT > 6 && V.len(c.vRel) < 0.03 && c.dist < 0.12){
      this._hardDock();
    }
  }

  if (!this.docked){
    const a = V.add(cwAccel(this.r, this.v), V.scl(Fh, 1/m));
    this.v = V.add(this.v, V.scl(a, DT));
    this.r = V.add(this.r, V.scl(this.v, DT));
    // chaser attitude
    const Iw = [INERTIA[0]*this.w[0], INERTIA[1]*this.w[1], INERTIA[2]*this.w[2]];
    const gyro = V.cross(this.w, Iw);
    for (let k=0;k<3;k++) this.w[k] += (Tb[k]-gyro[k]) / INERTIA[k] * DT;
    this.q = Q.norm(Q.mul(this.q, Q.fromRotVec(V.scl(this.w, DT))));
  }
  // target attitude (torque-free rigid body)
  const tIw = [this.tInertia[0]*this.tw[0], this.tInertia[1]*this.tw[1], this.tInertia[2]*this.tw[2]];
  const tg = V.cross(this.tw, tIw);
  for (let k=0;k<3;k++) this.tw[k] += -tg[k] / this.tInertia[k] * DT;
  this.tq = Q.norm(Q.mul(this.tq, Q.fromRotVec(V.scl(this.tw, DT))));
}

/* ---------- contact & capture ---------- */
_contactCheck(){
  if (this.docked || this.captured) return;
  if (V.len(this.r) > 8) return;
  this._updateContactMetrics();
  const c = this.contact;
  if (c.dist > GATE.range || this.contactCooldown > 0) return;
  const g = this.gatesPass(c);
  const ok = g.speed && g.lat && g.align && g.rate;
  this.lastContact = { t:this.t, rejected:!ok, gates:{...g},
    metrics:{ closing:c.closing, lateral:c.lateral, align:c.align, relRate:c.relRate } };
  if (ok){
    this.captured = true; this.captureT = 0;
    this.setPhase('SOFT CAPTURE', `contact within all gates (closing ${fmt(c.closing,3)} m/s, lateral ${fmt(c.lateral,2)} m, align ${fmt(c.align,1)}°, rel-rate ${fmt(c.relRate,2)}°/s). Capture ring engaged; damping residual motion before latching.`);
  } else {
    const bad = [];
    if (!g.speed) bad.push(c.closing > GATE.vmax ? `closing ${fmt(c.closing,2)} m/s > ${GATE.vmax}` : `closing ${fmt(c.closing,3)} m/s < ${GATE.vmin} (no engagement)`);
    if (!g.lat)   bad.push(`lateral ${fmt(c.lateral,2)} m > ${GATE.lat}`);
    if (!g.align) bad.push(`align ${fmt(c.align,1)}° > ${GATE.align}°`);
    if (!g.rate)  bad.push(`rel rate ${fmt(c.relRate,2)}°/s > ${GATE.rate}`);
    this.contactFails++;
    this.log('warn', `CONTACT REJECTED — mechanism refused capture: ${bad.join('; ')}. Vehicle bounced off the port (attempt ${this.contactFails}).`);
    // elastic bounce along the port normal + a small tumble kick
    const vn = V.dot(c.vRel, c.axis);                       // negative = ports approaching
    if (vn < 0) this.v = V.add(this.v, V.scl(c.axis, -(1+0.38)*vn));
    this.v = V.add(this.v, V.scl(c.axis, 0.02));
    this.w = V.add(this.w, [this.rand.gauss()*0.004, this.rand.gauss()*0.004, this.rand.gauss()*0.004]);
    this.r = V.add(this.r, V.scl(c.axis, 0.05));
    this.contactCooldown = 2.5;
  }
}
_hardDock(){
  this.docked = true; this.captured = false;
  this.qRelLock = Q.norm(Q.mul(Q.conj(this.tq), this.q));
  this.setPhase('HARD DOCK', 'structural latches closed with all residual rates damped. Rigid mate confirmed — rescue complete. Stack is safed.');
}
_dockedKinematics(){
  // chaser rides the target rigidly through the locked port transform
  this.q = Q.norm(Q.mul(this.tq, this.qRelLock));
  const pT = Q.rot(this.tq, PORT_T);
  this.r = V.sub(pT, Q.rot(this.q, PORT_C));
  const wT = Q.rot(this.tq, this.tw);
  this.v = V.cross(wT, pT);
  this.w = Q.rotInv(this.q, wT);
  for (const th of this.thr){ th.duty = 0; th.cmdImp = 0; th.achImp = 0; }
  this.Fb_cmd=[0,0,0]; this.Fb_ach=[0,0,0]; this.Tb_cmd=[0,0,0]; this.Tb_ach=[0,0,0];
}

/* ---------- test/debug placement (used by the self-test harness) ---------- */
_place(r, v, q, w, phase){
  this.r = r.slice(); this.v = v.slice();
  if (q) this.q = Q.norm(q.slice());
  if (w) this.w = w.slice();
  this.est.r = r.slice(); this.est.v = v.slice();
  for (let i=0;i<6;i++) for (let j=0;j<6;j++) this.est.P[i][j] = (i===j) ? (i<3?0.01:1e-4) : 0;
  this._ekfFinalize();
  if (phase){ this.phase = phase; this.phaseT = 0; }
  this._updateContactMetrics();
}

/* ---------- snapshot (JSON-safe) ---------- */
snapshot(){
  const c = this.contact, g = c ? this.gatesPass(c) : null;
  const round = (x)=>Math.round(x*1e6)/1e6;
  const v3 = (a)=>a.map(round);
  return {

  /* ---------- snapshot (JSON-safe) ---------- */
  snapshot(){
    const c = this.contact, g = c ? this.gatesPass(c) : null;
    const round = (x)=>Math.round(x*1e6)/1e6;
    const v3 = (a)=>a.map(round);
    return {
      time: round(this.t), scenario: this.scenario, seed: this.seed,
      mission: {
        phase: this.phase, auto: this.auto, docked: this.docked, captured: this.captured,
        aborted: this.aborted, abortReason: this.abortReason, contactFails: this.contactFails,
        navHold: this.navHold,
      },
      truth: {
        r: v3(this.r), v: v3(this.v), q: this.q.map(round), w: v3(this.w),
        targetQ: this.tq.map(round), targetW: v3(this.tw),
        range: round(V.len(this.r)),
        closing: round(-V.dot(this.r, this.v)/Math.max(V.len(this.r),1e-6)),
      },
      estimate: {
        r: v3(this.est.r), v: v3(this.est.v),
        sigmaPos: round(this.est.sigPos), sigmaVel: round(this.est.sigVel),
        targetAttSigmaDeg: round(this.est.tgtAttSig),
      },
      guidance: {
        phase: this.phase, attErrDeg: round(this.attErrDeg),
        corridorS: isFinite(this.corridorS) ? round(this.corridorS) : null,
      },
      actuators: {
        propellantKg: round(this.prop), propellantFrac: round(this.prop/PROP0),
        cmdForceN: round(V.len(this.Fb_cmd)), achForceN: round(V.len(this.Fb_ach)),
        thrusters: this.thr.map((th,i)=>({
          id: THR_DEFS[i].id, duty: round(th.duty),
          cmdImpulseTot: round(th.cmdTot), achImpulseTot: round(th.achTot),
          failedTruth: this.faults.thruster === i, isolatedByFDIR: th.isolated,
        })),
      },
      safety: {
        keepOutRadiusM: KOS_R, corridorHalfAngleDeg: round(CORR_HALF*DEG),
        gates: { rangeM: GATE.range, closingMinMs: GATE.vmin, closingMaxMs: GATE.vmax,
                 lateralM: GATE.lat, alignDeg: GATE.align, relRateDegS: GATE.rate },
        contact: c ? { dist: round(c.dist), axial: round(c.axial), lateral: round(c.lateral),
                       closing: round(c.closing), alignDeg: round(c.align), relRateDegS: round(c.relRate),
                       gatesPass: g } : null,
        lastContact: this.lastContact,
      },
      sensors: {
        lidar: this.sens.lidar, optical: this.sens.optical, imu: this.sens.imu,
        lidarRange: isFinite(this.sens.lidarRange) ? round(this.sens.lidarRange) : null,
        litFraction: round(this.sens.litFrac),
        faults: { ...this.faults },
      },
      events: this.events.slice(-10).map(e=>({ t: round(e.t), level: e.level, msg: e.msg })),
    };
  }
}

/* ---------------- engine wrapper: wall-clock → sim time (pause & scale live here) ---------------- */
class Engine {
  constructor(sim){ this.sim = sim; this.paused = false; this.scale = 1; }
  tick(realDt){
    if (this.paused) return 0;
    const s = Math.min(realDt, 0.1) * this.scale;   // cap frame delta: no physics explosions after tab suspend
    this.sim.advance(s);
    return s;
  }
}
