+    document.querySelectorAll('#speedSeg [data-speed]').forEach(b => b.setAttribute('aria-pressed', String(+b.dataset.speed===s)));
+  }
+  function syncScenarioBtns(){
+    document.querySelectorAll('[data-scn]').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.scn===sim.scenario)));
+  }
+  onSimReset = ()=>{
+    logRendered = 0; $('log').innerHTML = '';
+    if (hasGl){ world.ov.trailCount = 0; world.ov.trailLastT = -1; world.ov.trail.geometry.setDrawRange(0,0); }
+    syncScenarioBtns();
+    $('seedInput').value = sim.seed;
+    updateTelemetry(); drawPlots();
+  };
+  renderDiagResult = (r)=>{
+    $('diagBadge').className = 'st '+(r.passed?'s-nom':'s-abort');
+    $('diagBadge').textContent = r.passed ? 'PASS' : 'FAIL';
+    $('diagSummary').className = $('diagBadge').className;
+    $('diagSummary').textContent = (r.passed?'PASS':'FAIL')+` ${r.tests.filter(t=>t.pass).length}/${r.tests.length}`;
+    $('diagBody').innerHTML = r.tests.map(t =>
+      `<div class="dtest${t.pass?'':' fail'}"><span class="mk">${t.pass?'✓':'✕'}</span><div>${t.name}<small>${t.detail}</small></div></div>`
+    ).join('');
+  };
+
+  const on = (id, ev, fn) => $(id).addEventListener(ev, fn);
+  on('btnPlay','click', ()=> setPlay(!engine.paused));
+  on('btnStep','click', ()=>{ setPlay(true); sim.advance(0.25); updateTelemetry(); drawPlots(); if(hasGl) updateScene(); });
+  on('btnReset','click', ()=>{ sim.reset(parseInt($('seedInput').value,10)||1, sim.scenario); onSimReset(); });
+  on('btnApplySeed','click', ()=>{ sim.reset(parseInt($('seedInput').value,10)||1, sim.scenario); onSimReset(); });
+  document.querySelectorAll('#speedSeg [data-speed]').forEach(b => b.addEventListener('click', ()=> setScale(+b.dataset.speed)));
+  document.querySelectorAll('[data-scn]').forEach(b => b.addEventListener('click', ()=>{ sim.reset(parseInt($('seedInput').value,10)||1, b.dataset.scn); onSimReset(); }));
+  on('btnAuto','click', ()=>{ if (sim.auto) return; sim.log('info','Crew handed control back to the autonomous executive.'); sim.replan(); });
+  on('btnManual','click', ()=>{ if (!sim.auto) return; sim.auto=false; sim.log('caution','Crew took MANUAL control — autonomous guidance suspended, safety monitor remains armed.'); });
+  on('btnAbort','click', ()=> sim.abort('crew ABORT command'));
+  on('fltTumble','click', ()=> sim.setFault('tumble', !sim.faults.tumble));
+  on('fltLidar','click', ()=> sim.setFault('lidar', !sim.faults.lidar));
+  on('fltOptical','click', ()=> sim.setFault('optical', !sim.faults.optical));
+  on('fltThr','click', ()=>{
+    if (sim.faults.thruster >= 0) sim.setFault('thruster', false);
+    else sim.setFault('thruster', true, 0);
+  });
+  document.querySelectorAll('#camBtns [data-cam]').forEach(b => b.addEventListener('click', ()=> setCamMode(b.dataset.cam)));
+  on('btnResetView','click', resetView);
+  document.querySelectorAll('#ovGrid [data-ov]').forEach(inp => {
+    inp.checked = !!ovState[inp.dataset.ov];
+    inp.addEventListener('change', ()=>{ ovState[inp.dataset.ov] = inp.checked; });
+  });
+  on('btnClearLog','click', ()=>{ $('log').innerHTML=''; });
+  on('btnDiag','click', ()=>{ $('diag').hidden = false; });
+  on('btnOpenDiag','click', ()=>{ $('diag').hidden = false; });
+  on('btnCloseDiag','click', ()=>{ $('diag').hidden = true; });
+  on('btnRunTests','click', ()=>{ renderDiagResult(runSelfTestSuite()); $('diag').hidden = false; });
+
+  const tabs = { tabFly:'', tabCtl:'tab-right', tabTel:'tab-left', tabMore:'tab-right' };
+  for (const [id, cls] of Object.entries(tabs)){
+    on(id,'click', ()=>{
+      $('app').className = ($('app').classList.contains('manual')?'manual ':'')+cls;
+      for (const other of Object.keys(tabs)) $(other).setAttribute('aria-pressed', String(other===id));
+      layout();
+    });
+  }
+
+  const CMD_MAP = {
+    'tx+':['F',0, 1], 'tx-':['F',0,-1], 'ty+':['F',1, 1], 'ty-':['F',1,-1], 'tz+':['F',2, 1], 'tz-':['F',2,-1],
+    'rp+':['T',1,-1], 'rp-':['T',1, 1], 'ry+':['T',2, 1], 'ry-':['T',2,-1], 'rr+':['T',0, 1], 'rr-':['T',0,-1],
+  };
+  const KEY_CMD = { KeyW:'tx+', KeyS:'tx-', KeyA:'ty+', KeyD:'ty-', KeyR:'tz+', KeyF:'tz-',
+    ArrowUp:'rp+', ArrowDown:'rp-', ArrowLeft:'ry+', ArrowRight:'ry-', KeyQ:'rr-', KeyE:'rr+' };
+  const held = new Set();
+  function applyManualCmd(){
+    const F = [0,0,0], T = [0,0,0];
+    for (const c of held){
+      const m = CMD_MAP[c]; if (!m) continue;
+      (m[0]==='F' ? F : T)[m[1]] += m[2];
+    }
+    sim.manualCmd.F = F.map(x=>clamp(x,-1,1));
+    sim.manualCmd.T = T.map(x=>clamp(x,-1,1));
+  }
+  document.querySelectorAll('.padCluster .btn[data-cmd]').forEach(btn=>{
+    const c = btn.dataset.cmd;
+    const down = (e)=>{ e.preventDefault(); held.add(c); btn.classList.add('on'); };
+    const up = ()=>{ held.delete(c); btn.classList.remove('on'); };
+    btn.addEventListener('pointerdown', down);
+    btn.addEventListener('pointerup', up);
+    btn.addEventListener('pointerleave', up);
+    btn.addEventListener('pointercancel', up);
+  });
+  addEventListener('keydown', (e)=>{
+    if (e.target.closest('input,select,textarea')) return;
+    const cmd = KEY_CMD[e.code];
+    if (cmd && !sim.auto){ e.preventDefault(); held.add(cmd); return; }
+    if (e.code === 'Space' && !e.target.closest('button')){ e.preventDefault(); setPlay(!engine.paused); }
+    else if (e.code === 'Period'){ setPlay(true); sim.advance(CTRL_DT); }
+    else if (e.code === 'Digit1') setScale(0.25);
+    else if (e.code === 'Digit2') setScale(1);
+    else if (e.code === 'Digit3') setScale(4);
+    else if (e.code === 'KeyC' && hasGl) setCamMode(CAM_MODES[(CAM_MODES.indexOf(cam.mode)+1)%CAM_MODES.length]);
+    else if (e.code === 'Escape'){ $('diag').hidden = true; tourStop(); }
+  });
+  addEventListener('keyup', (e)=>{ const cmd = KEY_CMD[e.code]; if (cmd) held.delete(cmd); });
+  addEventListener('blur', ()=> held.clear());
+
+  const TOUR = [
+    { t:'Relative orbital motion', cam:'tgt', ov:{axes:true, trail:true, pred:true, kos:false, corridor:false},
+      b:'Everything here lives in the target-centred LVLH frame: V-BAR along the orbit, R-BAR toward zenith. Motion follows the Clohessy–Wiltshire equations, so coasting paths curve. Guidance fights this drift, not a vacuum.' },
+    { t:'Truth vs. estimate', cam:'chase', ov:{cov:true, sensors:true, trail:true},
+      b:'The autopilot never sees truth. A Kalman filter fuses lidar range and optical bearings into an estimate. The ellipsoid is 3σ position uncertainty. Kill the sensors and watch it swell; restore them and it snaps back.' },
+    { t:'Keep-out sphere and corridor', cam:'tgt', ov:{kos:true, corridor:true, guides:true},
+      b:'The 30 m keep-out sphere may only be entered through the approach cone aligned with the target docking axis. Anywhere else inside is an automatic abort. The corridor rotates with the tumbling target.' },
+    { t:'Attitude matching', cam:'dock', ov:{guides:true, corridor:true},
+      b:'In the final corridor the chaser must rotate with the tumbling target: port axes within 4°, relative spin under 0.8°/s. The gates panel scores every contact condition live.' },
+    { t:'Fault recovery', cam:'chase', ov:{},
+      b:'Inject a stuck thruster. Fault detection compares commanded impulse against IMU response, isolates the dead jet, and reallocates thrust. Scenario 3 scripts this end-to-end. Sensor blackout forces a hold or retreat.' },
+    { t:'Soft capture, then hard dock', cam:'dock', ov:{guides:true},
+      b:'Contact inside all gates engages a spring-damper capture ring that swallows residual motion before the latches close. Arrive too fast or misaligned and the mechanism refuses: you bounce. Physics, not a cut-scene.' },
+    { t:'Fly it yourself', cam:'cockpit', ov:{},
+      b:'Switch to Manual: W/S/A/D/R/F translate, arrows plus Q/E rotate. The safety monitor stays armed. Console API: __JANUS__.reset(seed), .setScenario(name), .step(s), .snapshot(), .runSelfTest().' },
+  ];
+  let tourIdx = -1, tourSaved = null;
+  function tourShow(){
+    const s = TOUR[tourIdx];
+    $('tourTitle').textContent = s.t;
+    $('tourStep').textContent = `STEP ${tourIdx+1}/${TOUR.length}`;
+    $('tourBody').textContent = s.b;
+    $('btnTourPrev').disabled = tourIdx === 0;
+    $('btnTourNext').textContent = tourIdx === TOUR.length-1 ? 'Finish' : 'Next';
+    if (hasGl) setCamMode(s.cam);
+    for (const [k,v] of Object.entries(s.ov)){
+      ovState[k] = v;
+      const inp = document.querySelector(`#ovGrid [data-ov="${k}"]`);
+      if (inp) inp.checked = v;
+    }
+    $('tour').hidden = false;
+  }
+  function tourStop(){
+    if (tourIdx < 0) return;
+    tourIdx = -1; $('tour').hidden = true;
+    if (tourSaved){
+      Object.assign(ovState, tourSaved);
+      document.querySelectorAll('#ovGrid [data-ov]').forEach(inp => { inp.checked = ovState[inp.dataset.ov]; });
+    }
+  }
+  on('btnTour','click', ()=>{ tourSaved = { ...ovState }; tourIdx = 0; tourShow(); });
+  on('btnTourNext','click', ()=>{ if (tourIdx >= TOUR.length-1) tourStop(); else { tourIdx++; tourShow(); } });
+  on('btnTourPrev','click', ()=>{ if (tourIdx > 0){ tourIdx--; tourShow(); } });
+  on('btnTourExit','click', tourStop);
+
+  addEventListener('resize', layout);
+  document.addEventListener('visibilitychange', ()=>{ lastT = performance.now(); });
+
+  let lastT = performance.now(), uiClock = 0, plotClock = 1;
+  function frame(now){
+    requestAnimationFrame(frame);
+    const dt = Math.min((now - lastT)/1000, 0.25); lastT = now;
+    applyManualCmd();
+    engine.tick(dt);
+    if (hasGl){ updateScene(); updateCamera(dt); }
+    uiClock += dt;
+    if (uiClock > 0.12){ uiClock = 0; updateTelemetry(); drainLog(); }
+    plotClock += dt;
+    if (plotClock > 0.25){ plotClock = 0; drawPlots(); }
+    if (hasGl) renderer.render(scene, camera);
+  }
+  layout();
+  syncScenarioBtns();
+  updateTelemetry();
+  drainLog();
+  if (hasGl) setCamMode('chase');
+  requestAnimationFrame(frame);
+  setTimeout(()=>{ renderDiagResult(runSelfTestSuite()); }, 400);
+}
+</script>
+</body>
+</html>

