const URL = 'http://127.0.0.1:8766/';

async function cdpCall(ws, id, method, params={}) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error('timeout '+method)), 60000);
    function onMsg(ev) {
      const msg = JSON.parse(ev.data);
      if (msg.id === id) {
        clearTimeout(t);
        ws.removeEventListener('message', onMsg);
        if (msg.error) reject(new Error(JSON.stringify(msg.error)));
        else resolve(msg.result);
      }
    }
    ws.addEventListener('message', onMsg);
    ws.send(JSON.stringify({ id, method, params }));
  });
}

(async () => {
  const created = await fetch('http://127.0.0.1:9223/json/new?' + encodeURIComponent(URL)).then(r => r.json());
  const ws = new WebSocket(created.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.addEventListener('open', res); ws.addEventListener('error', rej); });
  await cdpCall(ws, 1, 'Runtime.enable');
  await cdpCall(ws, 2, 'Page.enable');
  await cdpCall(ws, 3, 'Page.navigate', { url: URL });
  // wait for load
  await new Promise((resolve) => {
    function onMsg(ev) {
      const msg = JSON.parse(ev.data);
      if (msg.method === 'Page.loadEventFired') {
        ws.removeEventListener('message', onMsg);
        resolve();
      }
    }
    ws.addEventListener('message', onMsg);
  });
  // wait for __JANUS__
  let ready = false;
  for (let i=0;i<40;i++) {
    const r = await cdpCall(ws, 10+i, 'Runtime.evaluate', { expression: 'typeof window.__JANUS__', returnByValue: true });
    if (r.result.value === 'object') { ready = true; break; }
    await new Promise(r => setTimeout(r, 250));
  }
  const title = await cdpCall(ws, 100, 'Runtime.evaluate', { expression: 'document.title + "|" + document.querySelector("h1").textContent', returnByValue: true });
  const canvas = await cdpCall(ws, 101, 'Runtime.evaluate', { expression: '!!document.querySelector("canvas") && document.querySelector("canvas").width>0', returnByValue: true });
  const fatal = await cdpCall(ws, 102, 'Runtime.evaluate', { expression: 'document.getElementById("fatal") && !document.getElementById("fatal").hidden', returnByValue: true });
  console.log(JSON.stringify({ ready, title: title.result.value, canvas: canvas.result.value, fatalVisible: fatal.result.value }, null, 2));

  // wait for auto self-test
  await new Promise(r => setTimeout(r, 2500));
  const autoDiag = await cdpCall(ws, 110, 'Runtime.evaluate', { expression: 'document.getElementById("diagBadge").textContent', returnByValue: true });
  console.log('autoDiagBadge', autoDiag.result.value);

  const st = await cdpCall(ws, 111, 'Runtime.evaluate', {
    expression: `(async () => {
      const r = window.__JANUS__.runSelfTest();
      return { passed: r.passed, tests: r.tests };
    })()`,
    awaitPromise: true, returnByValue: true
  });
  console.log('selfTest', JSON.stringify(st.result.value, null, 2));

  const scenario = await cdpCall(ws, 112, 'Runtime.evaluate', {
    expression: `(() => {
      const a = window.__JANUS__.setScenario('sensor-blackout');
      const snap = window.__JANUS__.snapshot();
      const b = window.__JANUS__.setScenario('stuck-thruster');
      const snap2 = window.__JANUS__.snapshot();
      const c = window.__JANUS__.setScenario('nominal');
      return { a, scn2: snap2.scenario, phase: snap.mission.phase, scn3: c.scenario };
    })()`,
    returnByValue: true
  });
  console.log('scenarios', JSON.stringify(scenario.result.value));

  const pauseStep = await cdpCall(ws, 113, 'Runtime.evaluate', {
    expression: `(() => {
      window.__JANUS__.reset(7);
      const t0 = window.__JANUS__.snapshot().time;
      document.getElementById('btnPlay').click(); // pause
      const paused = document.getElementById('pauseBadge').hidden === false || document.getElementById('btnPlay').textContent === 'Play';
      const t1 = window.__JANUS__.step(1.0);
      const snap = window.__JANUS__.snapshot();
      return { t0, t1, time: snap.time, paused, playLabel: document.getElementById('btnPlay').textContent };
    })()`,
    returnByValue: true
  });
  console.log('pauseStep', JSON.stringify(pauseStep.result.value));

  const abort = await cdpCall(ws, 114, 'Runtime.evaluate', {
    expression: `(() => {
      window.__JANUS__.reset(9);
      window.__JANUS__.step(2);
      document.getElementById('btnAbort').click();
      window.__JANUS__.step(20);
      const s = window.__JANUS__.snapshot();
      return { phase: s.mission.phase, aborted: s.mission.aborted, range: s.truth.range };
    })()`,
    returnByValue: true
  });
  console.log('abort', JSON.stringify(abort.result.value));

  const cams = await cdpCall(ws, 115, 'Runtime.evaluate', {
    expression: `(() => {
      const labels = [];
      for (const cam of ['chase','tgt','dock','cockpit','free']) {
        const btn = document.querySelector('[data-cam="'+cam+'"]');
        btn.click();
        labels.push({ cam, hud: document.getElementById('hudCam').textContent, pressed: btn.getAttribute('aria-pressed') });
      }
      document.getElementById('btnResetView').click();
      return labels;
    })()`,
    returnByValue: true
  });
  console.log('cams', JSON.stringify(cams.result.value));

  const ovs = await cdpCall(ws, 116, 'Runtime.evaluate', {
    expression: `(() => {
      const out = {};
      document.querySelectorAll('#ovGrid [data-ov]').forEach(inp => {
        const before = inp.checked;
        inp.click();
        out[inp.dataset.ov] = { before, after: inp.checked };
      });
      return out;
    })()`,
    returnByValue: true
  });
  console.log('overlays', JSON.stringify(ovs.result.value));

  const cons = await cdpCall(ws, 117, 'Runtime.evaluate', {
    expression: `document.title === 'Cursor Grok 4.6' && document.querySelector('h1').textContent === 'Cursor Grok 4.6'`,
    returnByValue: true
  });
  console.log('titlesExact', cons.result.value);

  ws.close();
  process.exit(0);
})().catch(err => { console.error('FAIL', err); process.exit(1); });
END

