    document.querySelectorAll('#ovGrid [data-ov]').forEach(inp => {
      const before = inp.checked;
      inp.checked = !inp.checked;
      inp.dispatchEvent(new Event('change'));
      out[inp.dataset.ov] = { before, after: inp.checked };
    });
    return out;
  })()`);
  console.log('overlays', JSON.stringify(ovs));

  const faults = await evalv(`(() => {
    document.getElementById('fltLidar').click();
    document.getElementById('fltOptical').click();
    const s = window.__JANUS__.snapshot();
    document.getElementById('fltLidar').click();
    document.getElementById('fltOptical').click();
    return s.sensors.faults;
  })()`);
  console.log('faults', JSON.stringify(faults));

  process.exit(0);
})().catch(err => { console.error('FAIL', err); process.exit(1); });
